<script setup lang="ts">import type { PublishedGameSummary } from "@arcade/shared"; import FavoriteButton from "./FavoriteButton.vue"; import GameStatusBadge from "./GameStatusBadge.vue"; defineProps<{ game: PublishedGameSummary; favorite?: boolean }>(); const emit = defineEmits<{ favorite: []; play: [] }>();</script>
<template><article class="portal-game-card" :style="{ '--card-accent': game.accent ?? '#54d6ba' }"><RouterLink class="game-card-link" :to="`/zh/game/${game.slug}`"><div class="game-cover"><span v-if="game.cover_url" class="cover-image" :style="{ backgroundImage: `url(${game.cover_url})` }"></span><span v-else class="cover-letter portal-art-glyph">{{ game.legacy_icon || game.title.slice(0, 1) }}</span><GameStatusBadge :status="game.status" /></div><div class="game-card-copy"><span class="game-category">{{ game.categories[0]?.name ?? "休闲" }}</span><h3>{{ game.title }}</h3><p>{{ game.short_description }}</p><small>{{ game.developer_name }} · {{ game.orientation === "portrait" ? "竖屏" : "多方向" }}</small></div></RouterLink><FavoriteButton :active="favorite === true" :title="game.title" @toggle="emit('favorite')" /><button class="card-play" type="button" :disabled="game.status !== 'published'" @click="emit('play')">{{ game.status === "published" ? "开始" : "暂不可玩" }}</button></article></template>
